-- Demo data for the /live-demo page: agencies "Nexora Talent Partners" (/recq/nexora)
-- and "Brightline Staffing" (/recq/brightline), Portal Admin, agency recruiter, client
-- company "Finlytics Software Pvt Ltd" with its Company HR, jobs, fictional candidates
-- (*@mail.demo), applications, AI interview transcripts, reports and submissions.
-- Every account is on a non-routable .demo domain. All data is fictional.
--
-- 1. Inserts the demo set only when it is not there yet (owner@nexora.demo missing),
--    so databases that already have it (seeded with scripts/seed-demo.mjs) are untouched.
-- 2. Sets the password of the 5 demo logins listed on /live-demo, on every database.
--    That password must equal DEMO_PASSWORD in .env; turn the page on with DEMO_PAGE=true.
--    To change it later: npx tsx scripts/set-demo-password.mjs
-- 267 rows, generated from the local demo database with pg_dump.

DO $demo$
BEGIN
  IF EXISTS (SELECT 1 FROM "public"."users" WHERE "email" = 'owner@nexora.demo') THEN
    RAISE NOTICE 'Demo data already present - insert skipped';
    RETURN;
  END IF;

