INSERT INTO public.jobs (id, "companyId", title, description, "minimumExperience", "maximumExperience", "requiredSkills", "preferredSkills", "educationRequirements", location, "employmentType", status, "structuredRequirements", "createdBy", "createdAt", "updatedAt", "autoRejectBelowMinScore", "minAcceptableScore", "workMode", openings, "jobLevel", "noticePeriod", "languagesRequired", certifications, "salaryRange", "clientCompanyId", "departmentId", "hiringPersonId", "autoAdvanceOnMatch", "interviewFlow", "inviteValidDays", "autoSubmitToClient", "cvWeight", "finalThreshold", "interviewWeight", "interviewAvailabilityEnd", "interviewAvailabilityStart", slug) VALUES ('cmuwf0y7p000qwxxmx9jj7ceu', 'cmuwf0up90002wxxm4byz2ma7', 'AI/ML Engineer', 'Build and deploy machine learning models for credit risk and document understanding. You will train models in Python and PyTorch, build NLP pipelines, and take models to production with MLOps best practices.

You have 2–5 years of ML experience and an M.Tech/B.Tech in CS, Data Science or a related field.', 2, 5, '{Python,PyTorch,"Machine Learning",NLP,SQL,MLOps}', '{LLMs,MLOps,Docker,"AWS SageMaker"}', '{"M.Tech/B.Tech in CS, Data Science or related"}', 'Hyderabad', 'FULL_TIME', 'OPEN', '{"summary": "Build and deploy machine learning models for credit risk and document understanding.", "jobLevel": null, "location": null, "openings": null, "workMode": null, "education": ["M.Tech", "B.Tech", "Computer Science", "Data Science"], "salaryRange": null, "noticePeriod": null, "certifications": [], "employmentType": null, "requiredSkills": ["Python", "PyTorch", "NLP", "MLOps"], "preferredSkills": [], "languagesRequired": [], "maximumExperience": 5, "minimumExperience": 2}', 'cmuwf0up90001wxxmfqnz5gzh', '2026-10-06 08:27:16.405', '2026-10-06 08:27:19.766', false, 70, 'Hybrid', 1, 'Mid', NULL, '{}', '{}', '₹18–28 LPA', 'cmuwf0uxj000awxxmf371uwqa', 'cmuwf0uys000cwxxmwizcuamu', 'cmuwf0uzr000ewxxmoxqdasnm', false, 'INSTANT', 7, false, 0.3, 75, 0.7, '2026-10-16 08:27:12.493', '2026-09-28 08:27:12.493', 'ai-ml-engineer');
INSERT INTO public.jobs (id, "companyId", title, description, "minimumExperience", "maximumExperience", "requiredSkills", "preferredSkills", "educationRequirements", location, "employmentType", status, "structuredRequirements", "createdBy", "createdAt", "updatedAt", "autoRejectBelowMinScore", "minAcceptableScore", "workMode", openings, "jobLevel", "noticePeriod", "languagesRequired", certifications, "salaryRange", "clientCompanyId", "departmentId", "hiringPersonId", "autoAdvanceOnMatch", "interviewFlow", "inviteValidDays", "autoSubmitToClient", "cvWeight", "finalThreshold", "interviewWeight", "interviewAvailabilityEnd", "interviewAvailabilityStart", slug) VALUES ('cmuwf136v000ywxxmmnsd2lt5', 'cmuwf0up90002wxxm4byz2ma7', 'Backend Node.js Developer', 'Join the platform team that runs payment and ledger services. You will build reliable Node.js microservices on Express.js and PostgreSQL, containerise them with Docker, and own performance and observability.

What you will do:
- Design REST APIs and background workers in Node.js
- Model relational data in PostgreSQL and tune slow queries
- Add caching with Redis and messaging with Kafka where it helps
- Ship with Docker and CI/CD, and keep services observable

You have 3–6 years of backend experience with Node.js.', 3, 6, '{Node.js,Express.js,PostgreSQL,"REST APIs",Docker}', '{Redis,Kafka,AWS,Microservices,Express.js}', '{"B.E./B.Tech or MCA"}', 'Bengaluru', 'FULL_TIME', 'OPEN', '{"summary": "Join the platform team that runs payment and ledger services. You will build reliable Node.js microservices on Express.js and PostgreSQL, containerise them with Docker, and own performance and observability.", "jobLevel": null, "location": null, "openings": null, "workMode": null, "education": [], "salaryRange": null, "noticePeriod": null, "certifications": [], "employmentType": null, "requiredSkills": ["Node.js", "PostgreSQL", "Docker"], "preferredSkills": ["Express.js", "Redis", "Kafka"], "languagesRequired": [], "maximumExperience": 6, "minimumExperience": 3}', 'cmuwf0up90001wxxmfqnz5gzh', '2026-10-06 08:27:22.856', '2026-10-06 08:27:28.297', false, 65, 'On-site', 2, 'Senior', NULL, '{}', '{}', '₹16–24 LPA', 'cmuwf0uxj000awxxmf371uwqa', 'cmuwf0uys000cwxxmwizcuamu', 'cmuwf0uzr000ewxxmoxqdasnm', false, 'INSTANT', 7, false, 0.3, 70, 0.7, NULL, NULL, 'backend-nodejs-developer');
INSERT INTO public.jobs (id, "companyId", title, description, "minimumExperience", "maximumExperience", "requiredSkills", "preferredSkills", "educationRequirements", location, "employmentType", status, "structuredRequirements", "createdBy", "createdAt", "updatedAt", "autoRejectBelowMinScore", "minAcceptableScore", "workMode", openings, "jobLevel", "noticePeriod", "languagesRequired", certifications, "salaryRange", "clientCompanyId", "departmentId", "hiringPersonId", "autoAdvanceOnMatch", "interviewFlow", "inviteValidDays", "autoSubmitToClient", "cvWeight", "finalThreshold", "interviewWeight", "interviewAvailabilityEnd", "interviewAvailabilityStart", slug) VALUES ('cmuwf10um000uwxxmwuu5cddv', 'cmuwf0up90002wxxm4byz2ma7', 'React Developer', 'A remote contract role building customer-facing dashboards. You will turn Figma designs into fast, accessible React interfaces with Tailwind CSS and integrate them with REST APIs.

You have 1–3 years of React experience, strong JavaScript, HTML and CSS, and care about performance and accessibility.', 1, 3, '{React,JavaScript,HTML,CSS,"Tailwind CSS"}', '{TypeScript,Next.js,"Testing Library","Tailwind CSS","REST APIs"}', '{"Any graduate degree"}', 'Remote (India)', 'CONTRACT', 'OPEN', '{"summary": "A remote contract role building customer-facing dashboards. You will turn Figma designs into fast, accessible React interfaces.", "jobLevel": null, "location": null, "openings": null, "workMode": "Remote", "education": [], "salaryRange": null, "noticePeriod": null, "certifications": [], "employmentType": "CONTRACT", "requiredSkills": ["React", "JavaScript", "HTML", "CSS"], "preferredSkills": ["Tailwind CSS", "REST APIs"], "languagesRequired": [], "maximumExperience": 3, "minimumExperience": 1}', 'cmuwf0up90001wxxmfqnz5gzh', '2026-10-06 08:27:19.822', '2026-10-06 08:27:22.82', false, 60, 'Remote', 2, 'Junior', NULL, '{}', '{}', '₹60–90k / month', NULL, NULL, NULL, false, 'INSTANT', 7, false, 0.3, NULL, 0.7, '2026-10-13 08:27:12.493', '2026-09-28 08:27:12.493', 'react-developer');
INSERT INTO public.jobs (id, "companyId", title, description, "minimumExperience", "maximumExperience", "requiredSkills", "preferredSkills", "educationRequirements", location, "employmentType", status, "structuredRequirements", "createdBy", "createdAt", "updatedAt", "autoRejectBelowMinScore", "minAcceptableScore", "workMode", openings, "jobLevel", "noticePeriod", "languagesRequired", certifications, "salaryRange", "clientCompanyId", "departmentId", "hiringPersonId", "autoAdvanceOnMatch", "interviewFlow", "inviteValidDays", "autoSubmitToClient", "cvWeight", "finalThreshold", "interviewWeight", "interviewAvailabilityEnd", "interviewAvailabilityStart", slug) VALUES ('cmuwf17fu0012wxxmkrrqdq08', 'cmuwf0up90002wxxm4byz2ma7', 'MERN Stack Developer', 'Finlytics is building a modern lending platform. As a MERN Stack Developer you will design and ship features end to end with MongoDB, Express.js, React and Node.js, build secure REST APIs, and work closely with product and design.

What you will do:
- Build React interfaces with clean, reusable components and Redux state management
- Design and secure Node.js / Express REST APIs (JWT auth, validation, rate limiting)
- Model data in MongoDB and keep queries fast
- Write tests and review code

