INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwfa1vn00fhwxxm3ywwd65q', 'cmuwf9yye00ffwxxm09jh45bx', 'I think to ensure styles match the design, I would use CSS frameworks like Tailwind CSS, which is, um, pretty flexible? For responsive layouts, I guess I would use media queries and maybe some grid systems in CSS? It’s important to check how it looks on different devices, but I’m not exactly sure about the specifics.', 28, false, '{"note": "The answer was vague and lacked depth on implementation.", "relevance": 60, "needsFollowUp": false, "missingConcepts": ["specific techniques for matching design", "implementation details for media queries", "examples of grid systems"], "followUpQuestion": "Can you provide more details on how you would implement media queries and grid systems for responsive layouts?"}', '2026-10-02 09:05:01', NULL, false, 'I think to ensure styles match the design, I would use CSS frameworks like Tailwind CSS, which is, pretty flexible? For responsive layouts, I guess I would use media queries and maybe some grid systems in CSS? It’s important to check how it looks on different devices, but I’m not exactly sure about the specifics.', 'I think to ensure styles match the design, I would use CSS frameworks like Tailwind CSS, which is, um, pretty flexible? For responsive layouts, I guess I would use media queries and maybe some grid systems in CSS? It’s important to check how it looks on different devices, but I’m not exactly sure about the specifics.', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwfau3100g9wxxm5iu1cvv2', 'cmuwfar9m00g5wxxmzqx4wr9g', 'Uh, I haven''t really worked on that specifically. I think tokens are just like, used for identifying requests or something, but I''m not too sure about the details.', 16, false, '{"note": "Candidate lacks experience and understanding of key concepts.", "relevance": 30, "needsFollowUp": false, "missingConcepts": ["request tracking", "token generation", "rate limiting mechanisms"], "followUpQuestion": "Can you explain what you understand about how tokens are generated and validated in the context of rate limiting?"}', '2026-10-02 10:09:51', NULL, false, ', I haven''t really worked on that specifically. I think tokens are just like, used for identifying requests or something, but I''m not too sure about the details.', 'Uh, I haven''t really worked on that specifically. I think tokens are just like, used for identifying requests or something, but I''m not too sure about the details.', 0.82);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwf5rgq00cxwxxmh6kdwp4k', 'cmuwf5m7b00cpwxxm8rum4f7v', 'Hi Ananya, I’m Priya Sharma, a full-stack MERN developer with four years of experience specializing in high-traffic web applications, particularly in the FinTech and e-commerce sectors. Currently, I work at PayNest Technologies, where I built a loan-application portal using React, TypeScript, and Redux Toolkit, which serves around 120,000 customers monthly. I also designed secure REST APIs with Node.js and Express, implementing JWT for authentication and improving performance significantly. Before that, at CartCraft Labs, I focused on developing checkout and order-tracking features and increased test coverage to 80% using Jest. I hold a degree in Computer Engineering from Savitribai Phule Pune University and I’m an AWS Certified Developer. I''m excited about the opportunity to contribute my skills at Nexora!', 55, false, '{"note": "Candidate provided a comprehensive overview of their background and experience.", "relevance": 95, "needsFollowUp": false, "missingConcepts": [], "followUpQuestion": ""}', '2026-10-01 06:48:29', NULL, false, 'Hi Ananya, I’m Priya Sharma, a full-stack MERN developer with four years of experience specializing in high-traffic web applications, particularly in the FinTech and e-commerce sectors. Currently, I work at PayNest Technologies, where I built a loan-application portal using React, TypeScript, and Redux Toolkit, which serves around 120,000 customers monthly. I also designed secure REST APIs with Node.js and Express.js, implementing JWT for authentication and improving performance significantly. Before that, at CartCraft Labs, I focused on developing checkout and order-tracking features and increased test coverage to 80% using Jest. I hold a degree in Computer Engineering from Savitribai Phule Pune University and I’m an AWS Certified Developer. I''m excited about the opportunity to contribute my skills at Nexora!', 'Hi Ananya, I’m Priya Sharma, a full-stack MERN developer with four years of experience specializing in high-traffic web applications, particularly in the FinTech and e-commerce sectors. Currently, I work at PayNest Technologies, where I built a loan-application portal using React, TypeScript, and Redux Toolkit, which serves around 120,000 customers monthly. I also designed secure REST APIs with Node.js and Express, implementing JWT for authentication and improving performance significantly. Before that, at CartCraft Labs, I focused on developing checkout and order-tracking features and increased test coverage to 80% using Jest. I hold a degree in Computer Engineering from Savitribai Phule Pune University and I’m an AWS Certified Developer. I''m excited about the opportunity to contribute my skills at Nexora!', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwf89an00ebwxxmr93mew5r', 'cmuwf85n200e9wxxmhej259g1', 'One challenging system design problem I faced was while working on the ledger service at LedgerLoop, which processes around 2 million transactions daily. The main issue was the performance bottleneck due to high latency in transaction processing. To tackle this, I focused on database modeling and implemented Redis caching to store frequently accessed data, which significantly reduced the load on PostgreSQL. I also introduced idempotency keys to prevent duplicate processing. As a result, we saw the p95 latency drop from 480 milliseconds to just 120 milliseconds. This approach not only improved performance but also increased the reliability of our service under heavy load.', 49, false, '{"note": "The candidate provided a solid overview but could expand on database modeling specifics.", "relevance": 90, "needsFollowUp": true, "missingConcepts": ["database schema design", "indexing strategies", "query optimization"], "followUpQuestion": "Can you elaborate on the specific database modeling techniques you used to optimize performance?"}', '2026-10-01 07:58:53', NULL, false, 'One challenging system design problem I faced was while working on the ledger service at LedgerLoop, which processes around 2 million transactions daily. The main issue was the performance bottleneck due to high latency in transaction processing. To tackle this, I focused on database modeling and implemented Redis caching to store frequently accessed data, which significantly reduced the load on PostgreSQL. I also introduced idempotency keys to prevent duplicate processing. As a result, we saw the p95 latency drop from 480 milliseconds to just 120 milliseconds. This approach not only improved performance but also increased the reliability of our service under heavy load.', 'One challenging system design problem I faced was while working on the ledger service at LedgerLoop, which processes around 2 million transactions daily. The main issue was the performance bottleneck due to high latency in transaction processing. To tackle this, I focused on database modeling and implemented Redis caching to store frequently accessed data, which significantly reduced the load on PostgreSQL. I also introduced idempotency keys to prevent duplicate processing. As a result, we saw the p95 latency drop from 480 milliseconds to just 120 milliseconds. This approach not only improved performance but also increased the reliability of our service under heavy load.', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwf8mlg00ejwxxmda0s1wth', 'cmuwf8hdl00ehwxxmmex4yl22', 'Absolutely. At LedgerLoop, we faced a critical issue where our ledger service was experiencing high latency, affecting transaction processing. I started by checking the logs to identify any unusual patterns in the requests. I found that a specific database query was causing delays due to increased load. 

To resolve this, I analyzed the query execution plan and discovered missing indexes on the PostgreSQL tables. After creating the necessary indexes, I monitored the performance, which improved significantly. Additionally, I implemented Redis caching to further reduce the database load. As a result, the p95 latency dropped from 480 ms to 120 ms, enhancing user experience and system reliability. This proactive approach not only solved the immediate issue but also optimized our service for future loads.', 57, false, '{"note": "Candidate provided a detailed and relevant answer with specific metrics.", "relevance": 95, "needsFollowUp": false, "missingConcepts": [], "followUpQuestion": ""}', '2026-10-01 08:01:15', NULL, false, 'Absolutely. At LedgerLoop, we faced a critical issue where our ledger service was experiencing high latency, affecting transaction processing. I started by checking the logs to identify any unusual patterns in the requests. I found that a specific database query was causing delays due to increased load. To resolve this, I analyzed the query execution plan and discovered missing indexes on the PostgreSQL tables. After creating the necessary indexes, I monitored the performance, which improved significantly. Additionally, I implemented Redis caching to further reduce the database load. As a result, the p95 latency dropped from 480 ms to 120 ms, enhancing user experience and system reliability. This proactive approach not only solved the immediate issue but also optimized our service for future loads.', 'Absolutely. At LedgerLoop, we faced a critical issue where our ledger service was experiencing high latency, affecting transaction processing. I started by checking the logs to identify any unusual patterns in the requests. I found that a specific database query was causing delays due to increased load. 

To resolve this, I analyzed the query execution plan and discovered missing indexes on the PostgreSQL tables. After creating the necessary indexes, I monitored the performance, which improved significantly. Additionally, I implemented Redis caching to further reduce the database load. As a result, the p95 latency dropped from 480 ms to 120 ms, enhancing user experience and system reliability. This proactive approach not only solved the immediate issue but also optimized our service for future loads.', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwf9lwv00f5wxxmv9a1rvfm', 'cmuwf9iei00f3wxxmjxal5hce', 'I think to make a React page fast, you should, um, use techniques like code splitting and maybe optimize images. For accessibility, it''s important to use semantic HTML and ARIA roles, I believe. Also, ensuring proper keyboard navigation is, like, essential. But, I''m not sure about specific tools or metrics to measure these things.', 27, false, '{"note": "Candidate provided some good points but lacked depth on tools and metrics.", "relevance": 75, "needsFollowUp": true, "missingConcepts": ["performance metrics", "accessibility tools", "best practices for optimization"], "followUpQuestion": "Can you elaborate on specific tools or metrics you would use to measure performance and accessibility?"}', '2026-10-02 09:02:43', NULL, false, 'I think to make a React page fast, you should, use techniques like code splitting and maybe optimize images. For accessibility, it''s important to use semantic HTML and ARIA roles, I believe. Also, ensuring proper keyboard navigation is, like, essential. But, I''m not sure about specific tools or metrics to measure these things.', 'I think to make a React page fast, you should, um, use techniques like code splitting and maybe optimize images. For accessibility, it''s important to use semantic HTML and ARIA roles, I believe. Also, ensuring proper keyboard navigation is, like, essential. But, I''m not sure about specific tools or metrics to measure these things.', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwf9xo100fdwxxmfrhajzq1', 'cmuwf9uve00fbwxxmemb82z5x', 'I think to convert a design from Figma to a React component, I would start by analyzing the layout and identifying the different elements. Then, I would create a component structure in React, using Tailwind CSS for styling. Maybe some challenges could be ensuring that the styles match the design exactly or dealing with responsive layouts, but I’m not too sure.', 31, false, '{"note": "The answer was somewhat vague and lacked depth in the implementation process.", "relevance": 70, "needsFollowUp": true, "missingConcepts": ["specific steps for implementation", "handling design tokens", "testing for cross-browser compatibility"], "followUpQuestion": "Can you elaborate on how you would ensure the styles match the design and how you would handle responsive layouts?"}', '2026-10-02 09:04:16', NULL, false, 'I think to convert a design from Figma to a React component, I would start by analyzing the layout and identifying the different elements. Then, I would create a component structure in React, using Tailwind CSS for styling. Maybe some challenges could be ensuring that the styles match the design exactly or dealing with responsive layouts, but I’m not too sure.', 'I think to convert a design from Figma to a React component, I would start by analyzing the layout and identifying the different elements. Then, I would create a component structure in React, using Tailwind CSS for styling. Maybe some challenges could be ensuring that the styles match the design exactly or dealing with responsive layouts, but I’m not too sure.', 0.94);
INSERT INTO public.interview_answers (id, "questionId", transcript, "durationSeconds", "timedOut", evaluation, "answeredAt", "correctedTranscript", "manuallyCorrected", "normalizedTranscript", "rawTranscript", "sttConfidence") VALUES ('cmuwfa5y400flwxxm9hdtw61l', 'cmuwfa30g00fjwxxm47totlz1', 'I think I don''t have any questions right now, but I''m curious about the team structure, like, how many people would I be working with? That sounds important for collaboration, I guess.', 18, false, '{"note": "Candidate''s curiosity is good, but needs to explore the concept of collaboration further.", "relevance": 75, "closingReply": "Thank you for your interest! The recruiting team will follow up with details about the team structure and collaboration. I appreciate your time today, and this concludes our interview.", "needsFollowUp": false, "missingConcepts": ["team dynamics", "collaboration tools", "role within the team"], "followUpQuestion": "Can you elaborate on what specific aspects of team structure are important to you for collaboration?"}', '2026-10-02 09:05:36', NULL, false, 'I think I don''t have any questions right now, but I''m curious about the team structure, like, how many people would I be working with? That sounds important for collaboration, I guess.', 'I think I don''t have any questions right now, but I''m curious about the team structure, like, how many people would I be working with? That sounds important for collaboration, I guess.', 0.94);



