INSERT INTO public.interview_reports (id, "interviewId", status, "overallScore", "technicalScore", "communicationScore", strengths, "areasForImprovement", "questionAnalysis", "resumeAlignment", reasoning, "aiModel", "errorMessage", "generatedAt", "createdAt", "updatedAt", "criteriaAssessment") VALUES ('cmuwf7chn00dpwxxmskn3cm1m', 'cmuwf1tqu002hwxxmxxthzlss', 'COMPLETED', 92, 95, 90, '{"Demonstrated strong technical knowledge of the MERN stack and related technologies.","Provided specific examples of performance optimization and security measures implemented.","Clearly articulated the end-to-end development process and trade-offs made."}', '{"Could provide more detail on specific MongoDB schema design considerations.","Could elaborate on the testing strategies used beyond just mentioning Jest.","Could discuss more about collaboration and team dynamics in project development."}', '[{"score": 95, "question": "Hi Priya, I''m Ananya, Senior Technical Recruiter at Nexora Talent Partners. Thanks for joining — let''s get started. Could you briefly introduce yourself and walk me through your background?", "relevance": 100, "strengths": ["Clear overview of relevant experience.", "Mentioned specific technologies and projects.", "Strong alignment with job requirements."], "questionId": "cmuwf5m7b00cpwxxm8rum4f7v", "correctness": 100, "answerSummary": "Introduced herself as a full-stack MERN developer with four years of experience, detailing her current role and past experiences.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The candidate provided a comprehensive introduction that accurately reflected her background and skills relevant to the position."}, {"score": 96, "question": "Walk me through a MERN application you built end to end. What exactly was your part?", "relevance": 100, "strengths": ["Detailed explanation of full-stack responsibilities.", "Specific mention of technologies used.", "Quantified impact of the application."], "questionId": "cmuwf5srq00czwxxmiyn9orla", "correctness": 100, "answerSummary": "Described leading the development of a loan-application portal, detailing responsibilities in both front-end and back-end development.", "communication": 90, "technicalDepth": 95, "missingConcepts": [], "evaluationReason": "The answer provided a thorough and accurate account of the candidate''s role in a specific project, showcasing technical depth."}, {"score": 96, "question": "Can you elaborate on any specific challenges you faced during the development process and how you overcame them?", "relevance": 100, "strengths": ["Identified specific challenges and solutions.", "Demonstrated problem-solving skills.", "Showed understanding of performance optimization."], "questionId": "cmuwf5yhd00d3wxxm3qext5w5", "correctness": 100, "answerSummary": "Discussed challenges with MongoDB performance and role-based access, detailing solutions implemented.", "communication": 90, "technicalDepth": 95, "missingConcepts": [], "evaluationReason": "The candidate effectively articulated challenges faced and the strategies used to overcome them, demonstrating strong problem-solving abilities."}, {"score": 95, "question": "How would you secure a Node.js REST API that handles customer financial data?", "relevance": 100, "strengths": ["Comprehensive list of security practices.", "Demonstrated understanding of secure API design.", "Relevant experience mentioned."], "questionId": "cmuwf62m000d7wxxmoh6j7z9b", "correctness": 100, "answerSummary": "Outlined several security measures including JWT, role-based access, data validation, HTTPS, and rate limiting.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The answer provided a thorough overview of security measures relevant to the role, showcasing the candidate''s technical knowledge."}, {"score": 96, "question": "Can you describe a specific instance where you had to make trade-offs while developing a feature in your MERN application, particularly regarding performance or security? What choices did you make and why?", "relevance": 100, "strengths": ["Clear explanation of trade-offs made.", "Demonstrated understanding of performance vs. security.", "Specific example provided."], "questionId": "cmuwf69f500dbwxxmasf909ob", "correctness": 100, "answerSummary": "Described trade-offs made between JWT implementation for security and performance optimization.", "communication": 90, "technicalDepth": 95, "missingConcepts": [], "evaluationReason": "The candidate effectively discussed trade-offs, demonstrating a nuanced understanding of the implications of design choices."}, {"score": 95, "question": "Can you discuss a specific feature you built in your loan-application portal that required careful consideration of both performance and security? What decisions did you make during the development process?", "relevance": 100, "strengths": ["Detailed explanation of feature considerations.", "Balanced focus on performance and security.", "Specific technologies and strategies mentioned."], "questionId": "cmuwf6gl100dfwxxm3a4ryxgw", "correctness": 100, "answerSummary": "Discussed user authentication and authorization feature, focusing on performance and security considerations.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The candidate provided a detailed account of a specific feature, showcasing her ability to balance performance and security effectively."}, {"score": 95, "question": "That covers everything on my side. Do you have any questions for us about the role or Nexora Talent Partners?", "relevance": 100, "strengths": ["Demonstrated interest in team dynamics.", "Engaged with the interviewer."], "questionId": "cmuwf6orq00djwxxmy9xb1pv2", "correctness": 100, "answerSummary": "Asked about team structure and collaboration.", "communication": 90, "technicalDepth": 0, "missingConcepts": [], "evaluationReason": "The candidate asked relevant questions, showing engagement, although it did not require technical depth."}]', '{"requiredSkillsMatched": ["MongoDB", "Express.js", "React", "Node.js", "REST APIs"], "requiredSkillsMissing": ["JavaScript"], "preferredSkillsMatched": ["TypeScript", "Jest"], "requiredSkillMatchScore": 83, "preferredSkillMatchScore": 50}', 'The candidate demonstrated strong technical knowledge and relevant experience in MERN stack development, particularly in security and performance optimization. Communication was clear and structured, making it easy to follow her thought process. However, there were minor gaps in discussing MongoDB schema design, which could be further explored.', NULL, NULL, '2026-10-01 06:55:13', '2026-10-01 06:54:53', '2026-10-06 08:35:43.182', '[{"verdict": "MET", "evidence": "Described JWT implementation for secure authentication in multiple answers.", "criterion": "Explains JWT/session authentication correctly"}, {"verdict": "MET", "evidence": "Mentioned using Redux Toolkit for state management in the loan-application portal.", "criterion": "Shows solid React state management (hooks, Redux or Context)"}, {"verdict": "PARTLY", "evidence": "Discussed optimizing MongoDB performance but did not elaborate on schema design.", "criterion": "Can reason about MongoDB schema design and indexes"}, {"verdict": "MET", "evidence": "Answers were well-structured and easy to follow throughout the interview.", "criterion": "Communicates clearly and structures answers"}]');
INSERT INTO public.interview_reports (id, "interviewId", status, "overallScore", "technicalScore", "communicationScore", strengths, "areasForImprovement", "questionAnalysis", "resumeAlignment", reasoning, "aiModel", "errorMessage", "generatedAt", "createdAt", "updatedAt", "criteriaAssessment") VALUES ('cmuwf9ccx00erwxxmwlf4ue65', 'cmuwf1zwh002ywxxmuhepgmkg', 'COMPLETED', 92, 95, 90, '{"Strong technical knowledge in Node.js, PostgreSQL, and Redis.","Demonstrated experience in performance tuning and database modeling.","Clear understanding of rate limiting and user tier management."}', '{"Could provide more detail on specific indexing strategies used.","Could elaborate on the monitoring tools used for performance tracking.","Could discuss more about the implications of scaling in a microservices architecture."}', '[{"score": 95, "question": "Hi Arjun, I''m Vikram, Engineering Manager at Nexora Talent Partners. Thanks for joining — let''s get started. Could you briefly introduce yourself and walk me through your background?", "relevance": 100, "strengths": ["Clear articulation of experience and current role.", "Mentioned specific technologies and achievements."], "questionId": "cmuwf7cqh00drwxxm8re9tsrz", "correctness": 100, "answerSummary": "The candidate introduced himself, highlighting 5 years of backend experience, focusing on Node.js and PostgreSQL, and detailing his current role and achievements.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The candidate provided a comprehensive overview of his background, demonstrating relevant experience and technical knowledge."}, {"score": 95, "question": "How would you design rate limiting for a public payments API?", "relevance": 100, "strengths": ["In-depth understanding of rate limiting algorithms.", "Practical application of Redis for implementation."], "questionId": "cmuwf7k9800e1wxxmoj1ype53", "correctness": 100, "answerSummary": "The candidate proposed a token bucket algorithm using Redis for rate limiting, detailing user token allocation and response handling.", "communication": 90, "technicalDepth": 90, "missingConcepts": ["Consideration of different rate limiting strategies."], "evaluationReason": "The answer was technically sound and relevant, showcasing a solid understanding of rate limiting mechanisms."}, {"score": 95, "question": "Can you elaborate on how you would handle different user tiers or roles in your rate limiting design?", "relevance": 100, "strengths": ["Clear differentiation of user tiers.", "Practical use of middleware for implementation."], "questionId": "cmuwf7tus00e5wxxmysphqi4w", "correctness": 100, "answerSummary": "The candidate discussed implementing different limits for user tiers using Redis and middleware in Express.js.", "communication": 90, "technicalDepth": 85, "missingConcepts": [], "evaluationReason": "The response was relevant and demonstrated a good understanding of user tier management in rate limiting."}, {"score": 95, "question": "Can you describe a challenging system design problem you''ve faced in building a microservice with Node.js and PostgreSQL, and how you approached database modeling and performance tuning to resolve it?", "relevance": 100, "strengths": ["Specific example of a real-world challenge.", "Effective use of caching and idempotency keys."], "questionId": "cmuwf85n200e9wxxmhej259g1", "correctness": 100, "answerSummary": "The candidate described a performance bottleneck in a ledger service and detailed his approach to database modeling and caching.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The answer provided a thorough analysis of a real challenge, showcasing technical depth and problem-solving skills."}, {"score": 95, "question": "Can you elaborate on the specific database modeling techniques you used to optimize performance?", "relevance": 100, "strengths": ["Detailed explanation of database optimization techniques.", "Clear understanding of performance implications."], "questionId": "cmuwf8agd00edwxxms94al0vy", "correctness": 100, "answerSummary": "The candidate discussed normalization, star schema, indexing, and partitioning for PostgreSQL optimization.", "communication": 90, "technicalDepth": 90, "missingConcepts": ["Could provide examples of specific indexes created."], "evaluationReason": "The candidate demonstrated a strong grasp of database modeling techniques relevant to performance optimization."}, {"score": 95, "question": "Can you discuss a time when you had to debug a production issue in one of your Node.js microservices, detailing the steps you took to identify and resolve the problem, particularly focusing on any database-related challenges you encountered?", "relevance": 100, "strengths": ["Clear step-by-step debugging process.", "Effective use of Redis caching to resolve issues."], "questionId": "cmuwf8hdl00ehwxxmmex4yl22", "correctness": 100, "answerSummary": "The candidate described debugging a latency issue, identifying a problematic query, and implementing indexes and caching.", "communication": 90, "technicalDepth": 90, "missingConcepts": [], "evaluationReason": "The response was thorough and demonstrated real production debugging experience with a focus on database challenges."}, {"score": 90, "question": "That covers everything on my side. Do you have any questions for us about the role or Nexora Talent Partners?", "relevance": 100, "strengths": ["Shows interest in team dynamics.", "Relevant question regarding collaboration."], "questionId": "cmuwf8nvq00elwxxmsk8s79hc", "correctness": 100, "answerSummary": "The candidate asked about team dynamics and collaboration with frontend development.", "communication": 90, "technicalDepth": 80, "missingConcepts": [], "evaluationReason": "The candidate''s question was relevant and demonstrated engagement with the role and team structure."}]', '{"requiredSkillsMatched": ["Node.js", "Express.js", "PostgreSQL", "REST APIs", "Docker"], "requiredSkillsMissing": [], "preferredSkillsMatched": ["Redis", "Kafka", "AWS", "Microservices", "Express.js"], "requiredSkillMatchScore": 100, "preferredSkillMatchScore": 100}', 'The candidate demonstrated strong technical knowledge and relevant experience throughout the interview. Their answers were accurate, relevant, and showed a deep understanding of backend development concepts, particularly in Node.js and PostgreSQL. Communication was clear, and they effectively articulated their experiences and problem-solving approaches.', NULL, NULL, '2026-10-01 08:02:22', '2026-10-01 08:02:02', '2026-10-06 08:35:43.393', '[{"verdict": "MET", "evidence": "The candidate discussed normalization, star schema, and indexing techniques.", "criterion": "Designs sensible relational schemas and indexes"}, {"verdict": "MET", "evidence": "The candidate implemented Redis caching and discussed performance tuning.", "criterion": "Understands scaling (caching, queues, horizontal scaling)"}, {"verdict": "MET", "evidence": "The candidate described a specific production issue and the steps taken to resolve it.", "criterion": "Has real production debugging experience"}]');
INSERT INTO public.interview_reports (id, "interviewId", status, "overallScore", "technicalScore", "communicationScore", strengths, "areasForImprovement", "questionAnalysis", "resumeAlignment", reasoning, "aiModel", "errorMessage", "generatedAt", "createdAt", "updatedAt", "criteriaAssessment") VALUES ('cmuwfbspr00gtwxxmf48ghutp', 'cmuwf2d8u003wwxxm7mmqgzjd', 'COMPLETED', 30, 25, 40, '{"Familiarity with Node.js and Express.js","Experience with REST APIs","Knowledge of PostgreSQL"}', '{"Understanding of rate limiting mechanisms","Ability to model relational data effectively","Experience with performance tuning and stored procedures"}', '[{"score": 60, "question": "Hi Karan, I''m Vikram, Engineering Manager at Nexora Talent Partners. Thanks for joining — let''s get started. Could you briefly introduce yourself and walk me through your background?", "relevance": 80, "strengths": ["Experience with backend development", "Familiarity with Node.js"], "questionId": "cmuwfainh00frwxxmyg8p4nq4", "correctness": 70, "answerSummary": "Candidate introduces himself and mentions experience with backend development, particularly Node.js, but indicates limited project experience.", "communication": 60, "technicalDepth": 30, "missingConcepts": ["Specific projects or achievements", "Depth of experience"], "evaluationReason": "The candidate provided a brief introduction but lacked depth in discussing specific projects or achievements."}, {"score": 27, "question": "How would you design rate limiting for a public payments API?", "relevance": 50, "strengths": [], "questionId": "cmuwfan2300g1wxxm1aygkmjh", "correctness": 20, "answerSummary": "Candidate admits to not having experience with rate limiting and provides vague ideas about tracking requests and tokens.", "communication": 30, "technicalDepth": 10, "missingConcepts": ["Specific rate limiting strategies", "Implementation details", "Understanding of tokens and their role"], "evaluationReason": "The candidate showed a lack of understanding of rate limiting, providing only vague ideas without technical depth."}, {"score": 27, "question": "Can you elaborate on how you would implement tracking requests and the role of tokens in rate limiting?", "relevance": 50, "strengths": [], "questionId": "cmuwfar9m00g5wxxmzqx4wr9g", "correctness": 20, "answerSummary": "Candidate again states lack of experience and provides a vague response about tokens.", "communication": 30, "technicalDepth": 10, "missingConcepts": ["Detailed explanation of request tracking", "Token management", "Rate limiting algorithms"], "evaluationReason": "The candidate''s response lacked substance and did not demonstrate a clear understanding of the topic."}, {"score": 45, "question": "Can you explain how you would model relational data in PostgreSQL for a payments system, and what considerations you would take into account for performance?", "relevance": 60, "strengths": ["Basic understanding of tables and indexes"], "questionId": "cmuwfaxln00gbwxxmgc062s5i", "correctness": 30, "answerSummary": "Candidate mentions tables and indexes but lacks specific knowledge about modeling relational data.", "communication": 40, "technicalDepth": 20, "missingConcepts": ["Specific table structures for payments", "Performance tuning strategies", "Normalization and relationships"], "evaluationReason": "The candidate provided a basic response but lacked depth and specific knowledge about modeling data in PostgreSQL."}, {"score": 45, "question": "Can you elaborate on what specific tables and indexes you would consider for a payments system?", "relevance": 60, "strengths": ["Basic understanding of transaction tables"], "questionId": "cmuwfb33h00gfwxxmjgc7ois6", "correctness": 30, "answerSummary": "Candidate acknowledges lack of direct experience and provides a vague response about tables for transactions.", "communication": 40, "technicalDepth": 20, "missingConcepts": ["Specific index types", "Detailed schema design", "Performance considerations"], "evaluationReason": "The candidate''s response was vague and did not demonstrate a clear understanding of the necessary database design."}, {"score": 50, "question": "In your current role at TechNova Services, could you describe how you maintained the Express.js REST APIs and what challenges you faced while working with PostgreSQL stored procedures?", "relevance": 70, "strengths": ["Experience maintaining APIs"], "questionId": "cmuwfb8rl00gjwxxmgg6jxs9l", "correctness": 40, "answerSummary": "Candidate states they ensured APIs were working but lacks experience with stored procedures.", "communication": 50, "technicalDepth": 20, "missingConcepts": ["Specific challenges faced", "Details on stored procedures", "Performance tuning"], "evaluationReason": "The candidate provided a basic overview of their role but lacked detail on challenges and specific technical work."}, {"score": 40, "question": "That covers everything on my side. Do you have any questions for us about the role or Nexora Talent Partners?", "relevance": 60, "strengths": ["Interest in team dynamics"], "questionId": "cmuwfbdnp00gnwxxm97wxv47r", "correctness": 50, "answerSummary": "Candidate expresses curiosity about team dynamics but lacks specific questions.", "communication": 40, "technicalDepth": 10, "missingConcepts": ["Specific role-related questions", "Interest in company culture", "Clarification on job responsibilities"], "evaluationReason": "The candidate showed some interest but did not ask any specific or insightful questions about the role."}]', '{"requiredSkillsMatched": ["Node.js", "Express.js", "PostgreSQL", "REST APIs", "Docker"], "requiredSkillsMissing": [], "preferredSkillsMatched": ["Redis", "Express.js"], "requiredSkillMatchScore": 100, "preferredSkillMatchScore": 40}', 'The candidate has some familiarity with the required technologies but lacks depth in understanding key concepts such as rate limiting, relational data modeling, and performance tuning. Their responses were often vague and did not demonstrate the necessary technical knowledge expected for the role. Overall, they showed potential but would need significant development in core areas to meet the job requirements.', NULL, NULL, '2026-10-02 10:12:37', '2026-10-02 10:12:17', '2026-10-06 08:35:43.644', '[{"verdict": "NOT_MET", "evidence": "Candidate provided vague responses about tables and indexes without specific details.", "criterion": "Designs sensible relational schemas and indexes"}, {"verdict": "NOT_MET", "evidence": "Candidate did not demonstrate understanding of scaling concepts in their responses.", "criterion": "Understands scaling (caching, queues, horizontal scaling)"}, {"verdict": "PARTLY", "evidence": "Candidate mentioned maintaining APIs but did not provide specific challenges or debugging experiences.", "criterion": "Has real production debugging experience"}]');
INSERT INTO public.interview_reports (id, "interviewId", status, "overallScore", "technicalScore", "communicationScore", strengths, "areasForImprovement", "questionAnalysis", "resumeAlignment", reasoning, "aiModel", "errorMessage", "generatedAt", "createdAt", "updatedAt", "criteriaAssessment") VALUES ('cmuwfaigw00fpwxxmsn3vxv00', 'cmuwf25yx003fwxxmdcmqwrm1', 'COMPLETED', 60, 55, 65, '{"Experience with React and CSS frameworks","Basic understanding of performance and accessibility concepts","Familiarity with Tailwind CSS"}', '{"Specific tools and metrics for performance and accessibility","Deeper understanding of responsive design techniques","More confidence in discussing REST APIs"}', '[{"score": 75, "question": "Hi Sneha, I''m Priya, Virtual HR at Nexora Talent Partners. Thanks for joining — let''s get started. Could you briefly introduce yourself and walk me through your background?", "relevance": 90, "strengths": ["Clear introduction of experience", "Mention of relevant skills"], "questionId": "cmuwf9chd00etwxxmdxs18hkc", "correctness": 80, "answerSummary": "Candidate introduced herself and mentioned her experience with React and CSS frameworks.", "communication": 70, "technicalDepth": 60, "missingConcepts": [], "evaluationReason": "The candidate provided a relevant introduction and highlighted her experience, but lacked depth in discussing her specific contributions or challenges faced."}, {"score": 68, "question": "How do you make a React page fast and accessible?", "relevance": 80, "strengths": ["Identified key techniques for performance and accessibility", "Mentioned semantic HTML and ARIA roles"], "questionId": "cmuwf9iei00f3wxxmjxal5hce", "correctness": 70, "answerSummary": "Candidate mentioned code splitting, semantic HTML, ARIA roles, and keyboard navigation.", "communication": 65, "technicalDepth": 60, "missingConcepts": ["Specific tools or metrics for measuring performance and accessibility", "More detailed performance optimization strategies"], "evaluationReason": "The candidate provided a basic understanding of performance and accessibility but lacked specific tools and metrics."}, {"score": 60, "question": "Can you elaborate on specific tools or metrics you would use to measure performance and accessibility?", "relevance": 70, "strengths": ["Mentioned Google Lighthouse as a performance tool"], "questionId": "cmuwf9nvf00f7wxxmk8w65bh3", "correctness": 60, "answerSummary": "Candidate mentioned Google Lighthouse and ARIA roles but was unsure about specific metrics.", "communication": 60, "technicalDepth": 50, "missingConcepts": ["Specific accessibility testing tools", "Detailed performance metrics"], "evaluationReason": "The candidate showed some awareness of performance tools but lacked depth and confidence in discussing metrics."}, {"score": 68, "question": "Can you describe how you would approach converting a design from Figma into a React component using Tailwind CSS, and what challenges you might face in that process?", "relevance": 80, "strengths": ["Identified key steps in the conversion process", "Recognized potential challenges"], "questionId": "cmuwf9uve00fbwxxmemb82z5x", "correctness": 70, "answerSummary": "Candidate discussed analyzing layout, creating component structure, and potential challenges.", "communication": 65, "technicalDepth": 60, "missingConcepts": ["Specific techniques for ensuring design accuracy", "Handling of responsive design in detail"], "evaluationReason": "The candidate provided a reasonable approach but lacked specific techniques and details on handling challenges."}, {"score": 58, "question": "Can you elaborate on how you would ensure the styles match the design and how you would handle responsive layouts?", "relevance": 70, "strengths": ["Mentioned Tailwind CSS for styling", "Recognized the importance of responsive design"], "questionId": "cmuwf9yye00ffwxxm09jh45bx", "correctness": 60, "answerSummary": "Candidate mentioned using Tailwind CSS and media queries but was unsure about specifics.", "communication": 60, "technicalDepth": 50, "missingConcepts": ["Detailed strategies for ensuring design fidelity", "Specific responsive design frameworks or methodologies"], "evaluationReason": "The candidate acknowledged important concepts but lacked depth and specific strategies for implementation."}, {"score": 96, "question": "That covers everything on my side. Do you have any questions for us about the role or Nexora Talent Partners?", "relevance": 100, "strengths": ["Engaged with the interviewer", "Showed interest in collaboration"], "questionId": "cmuwfa30g00fjwxxm47totlz1", "correctness": 100, "answerSummary": "Candidate expressed curiosity about team structure.", "communication": 80, "technicalDepth": 100, "missingConcepts": [], "evaluationReason": "The candidate asked a relevant question that demonstrated interest in the role and collaboration."}]', '{"requiredSkillsMatched": ["React", "JavaScript", "HTML", "CSS", "Tailwind CSS"], "requiredSkillsMissing": [], "preferredSkillsMatched": ["Tailwind CSS", "REST APIs"], "requiredSkillMatchScore": 100, "preferredSkillMatchScore": 40}', 'The candidate has a solid foundation in React and CSS frameworks, demonstrating relevant experience and understanding of basic performance and accessibility practices. However, there is a noticeable lack of depth in technical knowledge, particularly regarding specific tools and metrics for performance and accessibility, as well as responsive design techniques. Overall, the candidate shows potential but would benefit from further development in these areas.', NULL, NULL, '2026-10-02 09:06:07', '2026-10-02 09:05:47', '2026-10-06 08:35:43.511', '[{"verdict": "PARTLY", "evidence": "Candidate mentioned experience with React but did not elaborate on hooks or component design specifics.", "criterion": "Understands React hooks and component design"}, {"verdict": "MET", "evidence": "Candidate discussed performance techniques and accessibility practices like semantic HTML and ARIA roles.", "criterion": "Knows basic accessibility and performance practices"}]');



