INSERT INTO public.screening_results (id, "applicationId", status, "overallScore", "skillMatchScore", "experienceMatchScore", "educationMatchScore", "matchedSkills", "missingSkills", strengths, concerns, reasoning, "deterministicChecks", "aiModel", "errorMessage", "screenedAt", "createdAt", "updatedAt") VALUES ('cmuwf1tqj002ewxxmas8h216k', 'cmuwf1tqg002cwxxmtgromdyi', 'COMPLETED', 91, 82, 100, 100, '{MongoDB,Express.js,React,Node.js,"REST APIs",TypeScript,Jest,JavaScript,Redux,JWT,AWS}', '{JavaScript}', '{"4 years of relevant experience in MERN stack development","Experience in building secure REST APIs with JWT authentication","Strong background in MongoDB optimization","Proficient in TypeScript and Redux Toolkit","AWS Certified Developer – Associate certification"}', '{}', 'The candidate meets all the job requirements with a perfect match in skills, relevant experience, and educational background. They have demonstrated hands-on experience in all required technologies and have additional preferred skills, making them an excellent fit for the MERN Stack Developer position.', '{"education": {"score": 100, "meetsRequirement": true}, "experience": {"score": 100, "meetsRequirement": true}, "skillOverlap": {"score": 70, "matched": ["MongoDB", "Express.js", "React", "Node.js", "REST APIs", "TypeScript", "Jest"], "missing": ["JavaScript", "Redux", "AWS"]}, "requiredSkillsOnly": {"score": 83, "missing": ["JavaScript"]}}', 'openai/gpt-4o-mini', NULL, '2026-09-30 04:43:40', '2026-09-30 04:43:40', '2026-10-06 08:35:43.058');
INSERT INTO public.screening_results (id, "applicationId", status, "overallScore", "skillMatchScore", "experienceMatchScore", "educationMatchScore", "matchedSkills", "missingSkills", strengths, concerns, reasoning, "deterministicChecks", "aiModel", "errorMessage", "screenedAt", "createdAt", "updatedAt") VALUES ('cmuwf1zvx002vwxxmdinw6pka', 'cmuwf1zvr002twxxmd35er8ar', 'COMPLETED', 100, 100, 100, 100, '{Node.js,Express.js,PostgreSQL,"REST APIs",Docker,Redis,Kafka,AWS,Microservices}', '{}', '{"5 years of relevant backend experience","Current role as Senior Backend Engineer aligns with job level","Experience with payment and ledger services","Proficient in all required and preferred skills"}', '{}', 'The candidate has a strong match with the job requirements, possessing all the required and preferred skills. Their experience as a Senior Backend Engineer and their educational background meet the job''s criteria perfectly.', '{"education": {"score": 100, "meetsRequirement": true}, "experience": {"score": 100, "meetsRequirement": true}, "skillOverlap": {"score": 100, "matched": ["Node.js", "Express.js", "PostgreSQL", "REST APIs", "Docker", "Redis", "Kafka", "AWS", "Microservices", "Express.js"], "missing": []}, "requiredSkillsOnly": {"score": 100, "missing": []}}', 'openai/gpt-4o-mini', NULL, '2026-09-30 05:56:40', '2026-09-30 05:56:40', '2026-10-06 08:35:43.281');
INSERT INTO public.screening_results (id, "applicationId", status, "overallScore", "skillMatchScore", "experienceMatchScore", "educationMatchScore", "matchedSkills", "missingSkills", strengths, concerns, reasoning, "deterministicChecks", "aiModel", "errorMessage", "screenedAt", "createdAt", "updatedAt") VALUES ('cmuwf35pf005pwxxmgdvrk967', 'cmuwf35o7005nwxxmykvjdmz2', 'COMPLETED', 78, 70, 100, 64, '{SQL,"Power BI",Statistics,Excel,Python}', '{Excel,Python}', '{"Strong SQL and Excel skills","Experience with Power BI and data analysis projects","Relevant educational background in Computer Applications"}', '{}', 'The candidate possesses all the required skills for the Data Analyst Intern position, including SQL, Excel, Python, and Power BI. Additionally, they have a strong foundation in Statistics, which is a preferred skill. The candidate is a final-year student, aligning with the educational requirements, and has relevant project experience that demonstrates their ability to apply these skills in practical scenarios.', '{"education": {"score": 40, "meetsRequirement": false}, "experience": {"score": 100, "meetsRequirement": true}, "skillOverlap": {"score": 50, "matched": ["SQL", "Power BI", "Statistics"], "missing": ["Excel", "Python", "Tableau"]}, "requiredSkillsOnly": {"score": 50, "missing": ["Excel", "Python"]}}', 'openai/gpt-4o-mini', NULL, '2026-10-04 05:40:40', '2026-10-04 05:40:40', '2026-10-06 08:35:43.825');
