INSERT INTO public.screening_results (id, "applicationId", status, "overallScore", "skillMatchScore", "experienceMatchScore", "educationMatchScore", "matchedSkills", "missingSkills", strengths, concerns, reasoning, "deterministicChecks", "aiModel", "errorMessage", "screenedAt", "createdAt", "updatedAt") VALUES ('cmuwf2tcu004rwxxmhth7s3yc', 'cmuwf2tcr004pwxxmtgl6inqw', 'COMPLETED', 86, 76, 92, 100, '{MongoDB,Express.js,React,Node.js,JavaScript,"REST APIs"}', '{TypeScript,Redux,AWS,Jest}', '{"2.5 years of relevant MERN stack experience","B.Tech in Computer Science","Hands-on experience with building React interfaces and Express APIs"}', '{"Lack of experience with preferred skills such as TypeScript, Redux, AWS, and Jest"}', 'The candidate meets all the required skills for the MERN Stack Developer position and has the necessary educational background. They have 2.5 years of experience, which is within the required range, but their experience is primarily as a Full Stack Developer and an intern, which may not fully demonstrate the depth of experience expected for a mid-level role. Additionally, the candidate lacks experience with preferred skills that could enhance their fit for the role.', '{"education": {"score": 100, "meetsRequirement": true}, "experience": {"score": 100, "meetsRequirement": true}, "skillOverlap": {"score": 60, "matched": ["MongoDB", "Express.js", "React", "Node.js", "JavaScript", "REST APIs"], "missing": ["TypeScript", "Redux", "AWS", "Jest"]}, "requiredSkillsOnly": {"score": 100, "missing": []}}', 'openai/gpt-4o-mini', NULL, '2026-10-03 11:01:40', '2026-10-03 11:01:40', '2026-10-06 08:35:43.748');
INSERT INTO public.screening_results (id, "applicationId", status, "overallScore", "skillMatchScore", "experienceMatchScore", "educationMatchScore", "matchedSkills", "missingSkills", strengths, concerns, reasoning, "deterministicChecks", "aiModel", "errorMessage", "screenedAt", "createdAt", "updatedAt") VALUES ('cmuwf3ccq0066wxxmwi6syqxn', 'cmuwf3ccl0064wxxmxelrdl92', 'COMPLETED', 81, 84, 64, 100, '{Node.js,Express.js,PostgreSQL,"REST APIs",Docker,Redis,AWS}', '{Kafka,Microservices}', '{"Strong skills in Node.js and Express.js","Experience with PostgreSQL and Docker","Familiarity with REST APIs and Redis","Relevant educational background in Information Technology"}', '{"Total experience of 2 years is below the minimum requirement of 3 years","No experience mentioned with Kafka or Microservices"}', 'The candidate has a strong skill set that aligns well with the job requirements, particularly in Node.js, Express.js, PostgreSQL, REST APIs, and Docker. However, the candidate''s total experience of 2 years does not meet the minimum requirement of 3 years, which is a significant concern. Additionally, while the candidate has experience with Redis, they lack experience with Kafka and Microservices, which are preferred skills for the role.', '{"education": {"score": 100, "meetsRequirement": true}, "experience": {"score": 80, "meetsRequirement": false}, "skillOverlap": {"score": 80, "matched": ["Node.js", "Express.js", "PostgreSQL", "REST APIs", "Docker", "Redis", "AWS", "Express.js"], "missing": ["Kafka", "Microservices"]}, "requiredSkillsOnly": {"score": 100, "missing": []}}', 'openai/gpt-4o-mini', NULL, '2026-10-04 06:53:40', '2026-10-04 06:53:40', '2026-10-06 08:35:43.848');

